@Component("position-handler")
@ProcessingGroup("position-processing-group")
public class PositionEventHandler {
	
	// core constructor
	PositionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePositionEvent
     */
    @EventHandler
    public void handle( CreatePositionEvent event) {
        entityManager.persist(new Position(event.getPositionId(), event.getQuantity(), event.getAverageCost(), event.getMarketValue(), event.getPortfolio(), event.getSecurity()));
    }

    /*
     * @param	event UpdatePositionEvent
     */
    @EventHandler
    public Position handle( UpdatePositionEvent event) {
    	entityManager.merge(new Position(event.getPositionId(), event.getQuantity(), event.getAverageCost(), event.getMarketValue(), event.getPortfolio(), event.getSecurity()));
    }
    
    /*
     * @param	event DeletePositionEvent
     */
    @EventHandler
    public void on( DeletePositionEvent event) {
    	Position entity = new Position();
   
    	// ------------------------------------------
    	// apply the PositionId
    	// ------------------------------------------
    	entity.setPositionId( event.getPositionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PositionRepository positionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PositionEventHandler.class.getName());

}
